void main() {
    int[] left = {1, 4, 9};
    int[] right = {2, 3, 10, 12};
    int[] merged = new int[left.length + right.length];
    int i = 0, j = 0, k = 0, comparisons = 0;
    while (i < left.length && j < right.length) {
        comparisons++;
        if (left[i] <= right[j]) {
            merged[k++] = left[i++];
        } else {
            merged[k++] = right[j++];
        }
    }
    while (i < left.length) {
        merged[k++] = left[i++];
    }
    while (j < right.length) {
        merged[k++] = right[j++];
    }
    IO.println(Arrays.toString(merged) + " " + comparisons);
}
